#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <cctype>
using namespace std;

int main() {
    string s;
    cin >> s;

    vector<map<string, long long>> stack(1);
    int i = 0, len = s.size();
    while (i < len) {
        char ch = s[i];
        if (ch == '(') {
            stack.push_back({});
            i++;
        } else if (ch == ')') {
            i++;
            long long mult = 0;
            bool any = false;
            while (i < len && isdigit(s[i])) {
                mult = mult * 10 + (s[i++] - '0');
                any = true;
            }
            if (!any) mult = 1;
            map<string, long long> top = stack.back();
            stack.pop_back();
            for (auto& entry : top) stack.back()[entry.first] += entry.second * mult;
        } else {
            int j = i + 1;
            while (j < len && islower(s[j])) j++;
            string name = s.substr(i, j - i);
            i = j;
            long long count = 0;
            bool any = false;
            while (i < len && isdigit(s[i])) {
                count = count * 10 + (s[i++] - '0');
                any = true;
            }
            if (!any) count = 1;
            stack.back()[name] += count;
        }
    }
    string result;
    for (auto& entry : stack[0]) {
        result += entry.first;
        if (entry.second > 1) result += to_string(entry.second);
    }
    cout << result << "\n";

    return 0;
}

